//! Golden vectors for part 3 (layout path): Shapely primitives, geometry contracts,
//! `validate_layout`, framing and the layout solver, all generated by
//! `apps/backend/tests-golden/domain/gen_domain3.py` from the Python implementation.
//!
//! Normalization (identical in the generator): `checked_at` is dropped from reports. Nothing else.

mod common;

use serde_json::{Map, Value};
use ss_core::Contract;
use ss_domain::contracts::geometry::{
    Coord, DesignRevisionRequest, DesignVersion, FinishSpecification, FurniturePlacement,
    LayoutGenerationRequest, LayoutPreferences, RoomPolygon, RoomRequirement, SiteGeometry,
};
use ss_domain::contracts::procurement::{BillOfMaterials, BomItem, SupplierOffer};
use ss_domain::design::geometry::framing::{
    dominant_angle, frame_for_solver, is_solver_ready, largest_inner_rectangle, normalize_plan,
    MIN_FRAME_AREA,
};
use ss_domain::design::geometry::solver::{
    best_strips, check_solution, expand, generate_candidates, Axis, Placement, SolveStatus,
    Topology,
};
use ss_domain::geometry;
use ss_domain::spatial::validation::{min_dimension, validate_layout};

fn g(name: &str) -> Value {
    common::golden(&format!("domain/{name}"))
}

fn pts(v: &Value) -> Vec<Coord> {
    serde_json::from_value(v.clone()).expect("points")
}

fn f(v: &Value) -> f64 {
    v.as_f64().expect("number")
}

/// First difference between two JSON values, numbers compared within `tol` (0 = exact,
/// int/float distinguished).
fn diff(a: &Value, b: &Value, tol: f64, path: &str) -> Option<String> {
    match (a, b) {
        (Value::Object(x), Value::Object(y)) => {
            for k in x.keys().chain(y.keys()) {
                match (x.get(k), y.get(k)) {
                    (Some(p), Some(q)) => {
                        if let Some(d) = diff(p, q, tol, &format!("{path}.{k}")) {
                            return Some(d);
                        }
                    }
                    _ => return Some(format!("{path}.{k} missing on one side")),
                }
            }
            None
        }
        (Value::Array(x), Value::Array(y)) => {
            if x.len() != y.len() {
                return Some(format!("{path}: length {} vs {}", x.len(), y.len()));
            }
            x.iter()
                .zip(y)
                .enumerate()
                .find_map(|(i, (p, q))| diff(p, q, tol, &format!("{path}[{i}]")))
        }
        (Value::Number(p), Value::Number(q)) if tol > 0.0 => {
            let (p, q) = (
                p.as_f64().unwrap_or(f64::NAN),
                q.as_f64().unwrap_or(f64::NAN),
            );
            ((p - q).abs() > tol).then(|| format!("{path}: {p} vs {q}"))
        }
        _ if a == b => None,
        _ => Some(format!("{path}: {a} vs {b}")),
    }
}

fn assert_same(ours: &Value, theirs: &Value, tol: f64, ctx: &str) {
    if let Some(d) = diff(ours, theirs, tol, "") {
        panic!("{ctx}: differs at {d}\nRust:   {ours}\nPython: {theirs}");
    }
}

fn report_json(r: &ss_domain::contracts::geometry::GeometryValidationReport) -> Value {
    let mut v = common::to_value(r);
    if let Value::Object(m) = &mut v {
        m.remove("checked_at");
    }
    v
}

// ---- primitives ---------------------------------------------------------------------------------

#[test]
fn shapely_primitives_match_python() {
    let doc = g("part3_geometry.json");
    let mut exact = 0;
    let mut multi = 0;
    for c in doc["explain"].as_array().unwrap() {
        let p = pts(&c["points"]);
        let ours = geometry::explain_validity(&p);
        let theirs = c["reason"].as_str().unwrap();
        assert_eq!(
            ours == "Valid Geometry",
            theirs == "Valid Geometry",
            "validity of {p:?}: Rust {ours}, Python {theirs}"
        );
        let cands = geometry::invalidity_candidates(&p);
        if cands.len() <= 1 || theirs.starts_with("Too few") {
            assert_eq!(ours, theirs, "explain_validity({p:?})");
            exact += 1;
        } else {
            // Several invalid intersections: GEOS's pick depends on its index traversal; it must
            // be one of the ring's invalid intersections.
            assert!(
                cands.iter().any(|x| x == theirs),
                "{p:?}: {theirs} not in {cands:?}"
            );
            multi += 1;
            if ours == theirs {
                exact += 1;
            }
        }
        assert_eq!(
            geometry::polygon_area(&p).to_bits(),
            f(&c["area"]).to_bits(),
            "area of {p:?}"
        );
    }
    println!("explain_validity: {exact} identical, {multi} with several invalid intersections");
    for c in doc["min_dimension"].as_array().unwrap() {
        let p = pts(&c["points"]);
        let (ours, theirs) = (min_dimension(&p), f(&c["min_dimension"]));
        assert!(
            (ours - theirs).abs() <= 1e-9,
            "min_dimension({p:?}): {ours} vs {theirs}"
        );
    }
    let outers = &doc["outer_shapes"];
    for c in doc["contains"].as_array().unwrap() {
        let outer = pts(&outers[c["outer"].as_str().unwrap()]);
        let inner = pts(&c["inner"]);
        let ours = geometry::contains_with_tolerance(&outer, &inner, f(&c["eps"]));
        assert_eq!(
            ours,
            c["contains"].as_bool().unwrap(),
            "{} contains {inner:?}",
            c["outer"]
        );
    }
    for c in doc["segment_length"].as_array().unwrap() {
        let p = pts(&c["polygon"]);
        let a: Coord = serde_json::from_value(c["start"].clone()).unwrap();
        let b: Coord = serde_json::from_value(c["end"].clone()).unwrap();
        let ours = geometry::segment_length_inside(&p, a, b);
        assert!(
            (ours - f(&c["length"])).abs() <= 1e-9,
            "{p:?} ∩ {a:?}-{b:?}: {ours} vs {}",
            c["length"]
        );
    }
    for c in doc["intersection_area"].as_array().unwrap() {
        let (a, b) = (pts(&c["a"]), pts(&c["b"]));
        let ours = geometry::intersection_area(&a, &b);
        assert!(
            (ours - f(&c["area"])).abs() <= 1e-9,
            "{a:?} ∩ {b:?}: {ours} vs {}",
            c["area"]
        );
    }
    for c in doc["validate_ring"].as_array().unwrap() {
        let p = pts(&c["points"]);
        let ours = ss_domain::contracts::geometry::validate_ring(&p, "room polygon");
        match c.get("raises").and_then(Value::as_str) {
            None => assert!(ours.is_ok(), "{p:?}: {ours:?}"),
            Some(msg) => {
                let msg = msg.strip_prefix("ValueError: ").unwrap_or(msg);
                let e = ours.expect_err("Python raised");
                if geometry::invalidity_candidates(&p).len() <= 1 {
                    assert_eq!(e, msg, "{p:?}");
                } else {
                    assert!(e.starts_with("room polygon is not a valid polygon"), "{e}");
                }
            }
        }
    }
}

// ---- contracts ----------------------------------------------------------------------------------

fn validate_by_name(name: &str, doc: &Value) -> Result<Value, ss_core::ValidationError> {
    fn go<T: Contract>(doc: &Value) -> Result<Value, ss_core::ValidationError> {
        T::from_json_value(doc.clone()).map(|v| common::to_value(&v))
    }
    match name {
        "SiteGeometry" => go::<SiteGeometry>(doc),
        "RoomPolygon" => go::<RoomPolygon>(doc),
        "FurniturePlacement" => go::<FurniturePlacement>(doc),
        "FinishSpecification" => go::<FinishSpecification>(doc),
        "RoomRequirement" => go::<RoomRequirement>(doc),
        "LayoutPreferences" => go::<LayoutPreferences>(doc),
        "LayoutGenerationRequest" => go::<LayoutGenerationRequest>(doc),
        "DesignRevisionRequest" => go::<DesignRevisionRequest>(doc),
        "DesignVersion" => go::<DesignVersion>(doc),
        "BomItem" => go::<BomItem>(doc),
        "BillOfMaterials" => go::<BillOfMaterials>(doc),
        "SupplierOffer" => go::<SupplierOffer>(doc),
        other => panic!("unknown model {other}"),
    }
}

#[test]
fn contract_validation_matches_pydantic() {
    for c in g("part3_contracts.json").as_array().unwrap() {
        let name = c["model"].as_str().unwrap();
        let ours = validate_by_name(name, &c["input"]);
        match (ours, c.get("validation_error")) {
            (Ok(_), None) => {}
            (Err(e), Some(theirs)) => {
                let ours: Vec<Value> = e
                    .errors
                    .iter()
                    .map(|i| serde_json::json!({"type": i.kind, "loc": i.loc, "msg": i.msg}))
                    .collect();
                let theirs = theirs.as_array().unwrap();
                // serde stops at its first error (part 1, deviation 2): unknown fields and enum
                // values are reported alone.
                let serde_level = theirs.iter().any(|t| {
                    matches!(
                        t["type"].as_str(),
                        Some("extra_forbidden" | "enum" | "missing")
                    )
                });
                let multi_crossing = |m: &str| {
                    m.contains("is not a valid polygon")
                        && (m.contains("Self-intersection") || m.contains("Ring Self-intersection"))
                };
                if serde_level {
                    // serde stops at its first error (part 1, deviation 2): missing fields,
                    // unknown fields and enum values are reported alone, and that one error is
                    // among Python's.
                    assert_eq!(ours.len(), 1, "{name}: {ours:?}");
                    assert!(
                        theirs
                            .iter()
                            .any(|t| t["loc"] == ours[0]["loc"] && t["type"] == ours[0]["type"]),
                        "{name}: {ours:?} not among {theirs:?}"
                    );
                } else if ours != *theirs {
                    // A ring with several invalid intersections: GEOS's reported location
                    // depends on its index traversal (see geometry::explain_validity); the error
                    // items must otherwise agree.
                    assert_eq!(ours.len(), theirs.len(), "{name}: {ours:?} vs {theirs:?}");
                    for (o, t) in ours.iter().zip(theirs) {
                        let (om, tm) = (o["msg"].as_str().unwrap(), t["msg"].as_str().unwrap());
                        assert_eq!(o["loc"], t["loc"], "{name}");
                        assert_eq!(o["type"], t["type"], "{name}");
                        assert!(
                            om == tm || (multi_crossing(om) && multi_crossing(tm)),
                            "{name}: {om} vs {tm}"
                        );
                    }
                }
            }
            (ours, theirs) => panic!("{name} {}: Rust {ours:?}, Python {theirs:?}", c["input"]),
        }
    }
}

// ---- validate_layout ----------------------------------------------------------------------------

#[test]
fn validate_layout_matches_python() {
    let cases = g("part3_validation.json");
    let cases = cases.as_array().unwrap();
    assert!(cases.len() >= 40, "{} cases", cases.len());
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let site = SiteGeometry::from_json_value(c["site"].clone()).expect("site");
        let rooms: Vec<RoomPolygon> = serde_json::from_value(c["rooms"].clone()).expect("rooms");
        let reqs: Vec<RoomRequirement> =
            serde_json::from_value(c["requirements"].clone()).expect("requirements");
        let circ: Option<Vec<Vec<Coord>>> =
            serde_json::from_value(c["circulation"].clone()).expect("circulation");
        let report = validate_layout(&site, &rooms, &reqs, circ.as_deref());
        match (c.get("ok"), c.get("raises")) {
            (Some(theirs), _) => assert_same(&report_json(&report), theirs, 0.0, name),
            (None, Some(err)) => {
                // Shapely raises on this invalid polygon; Rust reports it.
                assert!(
                    report.issues.iter().any(|i| i.code == "INVALID_POLYGON"),
                    "{name}: Python raised {err}; Rust {:?}",
                    report.issues
                );
            }
            _ => panic!("{name}: malformed case"),
        }
    }
}

// ---- framing ------------------------------------------------------------------------------------

#[test]
fn framing_matches_python() {
    let doc = g("part3_framing.json");
    for c in doc["dominant_angle"].as_array().unwrap() {
        let p = pts(&c["coords"]);
        assert_eq!(
            dominant_angle(&p).to_bits(),
            f(&c["angle"]).to_bits(),
            "{p:?}"
        );
    }
    for c in doc["normalize_plan"].as_array().unwrap() {
        let name = c["name"].as_str().unwrap();
        let ours = normalize_plan(&c["input"]);
        match (ours, c.get("ok")) {
            (Ok(v), Some(theirs)) => assert_same(&v, theirs, 0.0, name),
            (Err(_), None) => {}
            (ours, theirs) => panic!("{name}: Rust {ours:?}, Python {theirs:?}"),
        }
    }
    let cases = doc["cases"].as_array().unwrap();
    assert!(cases.len() >= 16);
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let site = SiteGeometry::from_json_value(c["site"].clone()).expect("site");
        assert_eq!(
            dominant_angle(&site.floor_boundary),
            f(&c["dominant_angle"]),
            "{name}"
        );
        assert_eq!(
            is_solver_ready(&site),
            c["solver_ready"].as_bool().unwrap(),
            "{name}"
        );
        let rect = largest_inner_rectangle(&site.floor_boundary, 0.2);
        let theirs: Option<(f64, f64, f64, f64)> =
            serde_json::from_value(c["largest_inner_rectangle"].clone()).unwrap();
        match (rect, theirs) {
            (Some(a), Some(b)) => {
                for (x, y) in [(a.0, b.0), (a.1, b.1), (a.2, b.2), (a.3, b.3)] {
                    assert!((x - y).abs() <= 1e-9, "{name}: {a:?} vs {b:?}");
                }
            }
            (a, b) => assert_eq!(a, b, "{name}"),
        }
        let frame = frame_for_solver(&site, MIN_FRAME_AREA);
        match (frame, c["frame"].as_object()) {
            (None, None) => {}
            (Some(fr), Some(theirs)) => {
                assert_eq!(common::to_value(&fr.notes), theirs["notes"], "{name} notes");
                assert_same(&common::to_value(&fr.site), &theirs["site"], 1e-6, name);
                for probe in theirs["to_site"].as_array().unwrap() {
                    let p: Coord = serde_json::from_value(probe["p"].clone()).unwrap();
                    let q: Coord = serde_json::from_value(probe["q"].clone()).unwrap();
                    let ours = fr.to_site(p);
                    assert!(
                        (ours.0 - q.0).abs() <= 1e-9 && (ours.1 - q.1).abs() <= 1e-9,
                        "{name}: to_site({p:?}) = {ours:?}, Python {q:?}"
                    );
                }
            }
            (a, b) => panic!("{name}: Rust frame {a:?}, Python {b:?}"),
        }
    }
}

// ---- solver -------------------------------------------------------------------------------------

#[derive(Default, Debug)]
struct SolverStats {
    attempts: usize,
    python_optimal: usize,
    python_feasible: usize,
    python_infeasible: usize,
    python_prechecks: usize,
    feasible_rust_better: usize,
    feasible_rust_equal: usize,
    rust_optimal: usize,
    rust_constructive: usize,
    candidates: usize,
    python_valid_candidates: usize,
    rust_valid_candidates: usize,
    both_valid: usize,
}

fn placements_from(v: &Value) -> Vec<Placement> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|t| Placement {
            room: t[0].as_u64().unwrap() as usize,
            strip: t[1].as_u64().unwrap() as usize,
            start_cm: t[2].as_i64().unwrap(),
            length_cm: t[3].as_i64().unwrap(),
        })
        .collect()
}

#[test]
fn solver_matches_cp_sat_model() {
    let cases = g("part3_solver.json");
    let cases = cases.as_array().unwrap();
    assert!(cases.len() >= 40);
    let mut st = SolverStats::default();
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let site = SiteGeometry::from_json_value(c["site"].clone()).expect("site");
        let reqs: Vec<RoomRequirement> = serde_json::from_value(c["requirements"].clone()).unwrap();
        let prefs = LayoutPreferences::from_json_value(c["preferences"].clone()).unwrap();
        let count = c["count"].as_i64().unwrap();
        let frame = frame_for_solver(&site, MIN_FRAME_AREA);
        match (&frame, c["framed_site"].is_null()) {
            (None, true) => {}
            (Some(fr), false) => {
                assert_same(&common::to_value(&fr.site), &c["framed_site"], 1e-9, name)
            }
            _ => panic!("{name}: framing differs"),
        }
        let rooms = expand(&reqs).expect("program within MAX_ROOMS");
        for topo in c["topologies"].as_array().unwrap() {
            let topology = match topo["topology"].as_str().unwrap() {
                "spine" => Topology::Spine,
                _ => Topology::Front,
            };
            let framed = &frame.as_ref().expect("solved cases are framed").site;
            let choice = best_strips(framed, topology, &rooms, &prefs).unwrap();
            let theirs = topo["attempts"].as_array().unwrap();
            // Python moves to the next offset only when an attempt has no solution; Rust is exact
            // here, so it stops at the same offset whenever Python's statuses are proofs.
            assert_eq!(
                choice.attempts.len(),
                theirs.len(),
                "{name} {topology:?}: attempts"
            );
            for ((off, rep), py) in choice.attempts.iter().zip(theirs) {
                st.attempts += 1;
                let ctx = format!("{name} {topology:?} offset {off:?}");
                assert_eq!(common::to_value(off), py["offset"], "{ctx}");
                // Strips and circulation are Python's exactly.
                let strips_now = ss_domain::design::geometry::solver::strips(
                    framed,
                    topology,
                    prefs.circulation_width_m,
                    *off,
                )
                .unwrap();
                for (s, ps) in strips_now.0.iter().zip(py["strips"].as_array().unwrap()) {
                    assert_eq!(s.name, ps["name"], "{ctx}");
                    assert_eq!(
                        match s.axis {
                            Axis::X => "x",
                            Axis::Y => "y",
                        },
                        ps["axis"],
                        "{ctx}"
                    );
                    assert_eq!(common::to_value(&s.origin), ps["origin"], "{ctx}");
                    assert_eq!(s.span.to_bits(), f(&ps["span"]).to_bits(), "{ctx}");
                    assert_eq!(s.depth.to_bits(), f(&ps["depth"]).to_bits(), "{ctx}");
                    assert_eq!(common::to_value(&s.reserved), ps["reserved"], "{ctx}");
                }
                assert_eq!(common::to_value(&strips_now.1), py["circulation"], "{ctx}");
                let status = py["status"].as_str().unwrap();
                let proof = matches!(status, "OPTIMAL" | "INFEASIBLE" | "CAPACITY" | "NO_STRIP");
                match status {
                    "OPTIMAL" => st.python_optimal += 1,
                    "FEASIBLE" => st.python_feasible += 1,
                    "INFEASIBLE" => st.python_infeasible += 1,
                    _ => st.python_prechecks += 1,
                }
                let python_has = !py["solution"].is_null();
                if proof || python_has {
                    assert_eq!(
                        rep.status.has_solution(),
                        python_has,
                        "{ctx}: Rust {:?}, Python {status}",
                        rep.status
                    );
                }
                if matches!(status, "CAPACITY") {
                    assert_eq!(rep.status, SolveStatus::CapacityExceeded, "{ctx}");
                }
                if matches!(status, "NO_STRIP") {
                    assert_eq!(rep.status, SolveStatus::NoEligibleStrip, "{ctx}");
                }
                match rep.status {
                    SolveStatus::Optimal => st.rust_optimal += 1,
                    SolveStatus::Feasible => st.rust_constructive += 1,
                    _ => {}
                }
                if rep.status.has_solution() {
                    // Every hard constraint holds and the reported objective is the model's.
                    let obj =
                        check_solution(&strips_now.0, &rooms, framed, &prefs, &rep.placements)
                            .unwrap_or_else(|e| {
                                panic!("{ctx}: Rust solution breaks the model: {e}")
                            });
                    assert_eq!(Some(obj), rep.objective, "{ctx}");
                }
                if python_has {
                    // Python's solution satisfies the Rust model, with CP-SAT's objective value.
                    let py_pl = placements_from(&py["solution_cm"]);
                    let py_obj = check_solution(&strips_now.0, &rooms, framed, &prefs, &py_pl)
                        .unwrap_or_else(|e| {
                            panic!("{ctx}: Python's solution fails the Rust model: {e}")
                        });
                    let cp_obj = f(&py["objective"]);
                    assert_eq!(
                        py_obj as f64, cp_obj,
                        "{ctx}: objective of Python's solution"
                    );
                    let ours = rep.objective.expect("Rust solution");
                    if status == "OPTIMAL" {
                        assert_eq!(ours, py_obj, "{ctx}: both optimal");
                    } else {
                        assert!(ours >= py_obj, "{ctx}: Rust {ours} < CP-SAT {py_obj}");
                        if ours > py_obj {
                            st.feasible_rust_better += 1;
                        } else {
                            st.feasible_rust_equal += 1;
                        }
                    }
                }
            }
        }
        // Candidates: the same topologies and outcomes; Rust layouts pass the ported validator.
        let ours = generate_candidates(&site, &reqs, &prefs, count).unwrap();
        let theirs = c["candidates"].as_array().unwrap();
        assert_eq!(ours.len(), theirs.len(), "{name}");
        for (o, t) in ours.iter().zip(theirs) {
            st.candidates += 1;
            assert_eq!(o.name, t["name"], "{name}");
            assert_eq!(
                o.rooms.len(),
                t["rooms"].as_array().unwrap().len(),
                "{name} {}",
                o.name
            );
            let t_valid = t["report"]["valid"].as_bool().unwrap();
            if t_valid {
                st.python_valid_candidates += 1;
            }
            if o.report.valid {
                st.rust_valid_candidates += 1;
                if !t_valid {
                    println!(
                        "RUST_ONLY_VALID {name} {}: Python issues {}",
                        o.name, t["report"]["issues"]
                    );
                }
            }
            if t_valid && o.report.valid {
                st.both_valid += 1;
            }
            assert!(
                !t_valid || o.report.valid,
                "{name} {}: Python's candidate is valid, Rust's is not: {:?}",
                o.name,
                o.report.issues
            );
            if o.rooms.is_empty() {
                assert_same(&report_json(&o.report), &t["report"], 0.0, name);
            } else {
                assert_eq!(o.report.disclaimer, t["report"]["disclaimer"], "{name}");
                assert_eq!(
                    common::to_value(&o.circulation),
                    t["circulation"],
                    "{name} circulation"
                );
                for r in &o.rooms {
                    r.validate().unwrap();
                }
            }
        }
    }
    println!("{st:#?}");
}

#[test]
fn solver_output_is_deterministic() {
    let cases = g("part3_solver.json");
    for c in cases.as_array().unwrap().iter().take(20) {
        let site = SiteGeometry::from_json_value(c["site"].clone()).unwrap();
        let reqs: Vec<RoomRequirement> = serde_json::from_value(c["requirements"].clone()).unwrap();
        let prefs = LayoutPreferences::from_json_value(c["preferences"].clone()).unwrap();
        let strip_ts = |v: &Vec<ss_domain::design::geometry::solver::Candidate>| -> Value {
            let mut m = Map::new();
            for c in v {
                m.insert(c.name.clone(), common::to_value(&c.rooms));
            }
            Value::Object(m)
        };
        let a = generate_candidates(&site, &reqs, &prefs, 2).unwrap();
        let b = generate_candidates(&site, &reqs, &prefs, 2).unwrap();
        assert_eq!(strip_ts(&a), strip_ts(&b));
    }
}
